1024	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
1025	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
1026	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
1027	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
1028		shiftID = clean(shiftID)
1029		d := &svc.store.data
1030		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
1031		sh, _ := findShift(d, shiftID)
1032		if sh == nil {
1033			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
1034		}
1035		rep.Shift = *sh
1036	
1037		for _, n := range d.Notes {
1038			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
1039				rep.OverlapNotes = append(rep.OverlapNotes, n)
1040			}
1041		}
1042		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
1043	
1044		switch {
1045		case !sh.Closed:
1046			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
1047			rep.Items = currentItemsOfShift(d, sh.ID)
1048		case sh.CloseRecord != nil:
1049			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
1050			rep.ItemsAtClose = true
1051			rep.CloseItems = append([]CloseItemSnapshot(nil), sh.CloseRecord.Items...)
1052			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
1053			for _, s := range rep.CloseItems {
1054				if it, _ := findItem(d, s.ItemID); it != nil {
1055					rep.LatestItems[s.ItemID] = *it
1056				}
1057			}
1058		default:
1059			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
1060			rep.HistoryIncomplete = true
1061			rep.Items = currentItemsOfShift(d, sh.ID)
1062		}
1063		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
1064	
1065		for i := range d.Handovers {
1066			h := &d.Handovers[i]
1067			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
1068			if !involved {
1069				continue
1070			}
1071			if h.FromShiftID == sh.ID {
1072				cp := *h
1073				rep.Outgoing = &cp
1074			}
1075			if h.ToShiftID == sh.ID {
1076				rep.Incoming = append(rep.Incoming, *h)
1077			}
1078			for j := range h.Entries {
1079				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
1080					HandoverID: h.ID,
1081					FromShift:  h.FromShiftID,
1082					ToShift:    h.ToShiftID,
1083					Entry:      h.Entries[j],
1084				})
1085			}
1086		}
