// journeyKinds 提取处理经过的事件类型序列，便于断言顺序。
func journeyKinds(j ItemJourney) []string {
	kinds := make([]string, len(j.Events))
	for i, ev := range j.Events {
		kinds[i] = ev.Kind
	}
	return kinds
}

func joinStrings(xs []string) string {
	out := ""
	for i, x := range xs {
		if i > 0 {
			out += ","
		}
		out += x
	}
	return out
}

