    {"id":"S003","position":"调度","owner":"赵六","start":"2026-10-02T16:00:00+08:00","end":"2026-10-02T23:30:00+08:00","created_at":"2026-10-02T08:00:00+08:00","closed":true,"closed_at":"2026-10-02T23:30:00+08:00"}
